#include "stdafx.h"#include "ServerEx.h"#include "../ServerExBase/ServerThreadBase.h"#include <conio.h>#include <iostream>#include "resource.h"#include "YokoDefs.h"#include <Common.h>#include <CommProc.h>#include <Names.h>#include <SysDataTypes.h>#include "ExerciseState.h"#include "LogFile.h"void MyStart();void MyStop();LRESULT CALLBACK WindowFunc( HWND hWnd, UINT uMsg, WPARAM wParam, LPARAM lParam );#define NAME_WINDOW_SERVER      "Сетевой сервер"HICON hIcon;UINT nIconMessage = ::RegisterWindowMessageA("¨лочка гори!!!");UINT nYokoMessage = ::RegisterWindowMessageA(YOKO_KBD_MSG);HWND g_hWnd = NULL;int  b_hWnd = false;bool bDebugWnd = false;CExerciseState g_cExrcState;CExerciseState& GetExrcState (){	return g_cExrcState;}int WINAPI WinMain( HINSTANCE hInstance, HINSTANCE , LPSTR pszCmdLine, int nWinMode ){    ASS(InitNamesAndVariables( false, false ));  GiveCommData( "Модель", CExternalCondition::TypeID, (void**)&pExt );  GiveCommData( "Модель", CSystem::TypeID, (void**)&pSys );  LoadPlugins();  //  if ( pszCmdLine[0] == '/' || pszCmdLine[0] == '-' )  if ( pszCmdLine[1] == 'd' || pszCmdLine[1] == 'D' )    {    bDebugWnd = true;    }  HWND hWnd = ::FindWindow( NAME_CLASS_SERVER, NULL );  if ( ::IsWindow( hWnd ) )    {    //MessageBox(NULL,NAME_CLASS_SERVER,NULL,0);    return 0; //Запрет на несколько экземпляров сервера    }  //  MSG msg;  WNDCLASS wcl;  //  hIcon = ::LoadIcon(hInstance,MAKEINTRESOURCE(IDI_ICON1));  //  wcl.hInstance     = hInstance;  wcl.lpszClassName = NAME_CLASS_SERVER;  wcl.lpfnWndProc   = WindowFunc;  wcl.style = 0;  //  wcl.hIcon   = hIcon;  wcl.hCursor = ::LoadCursor( NULL, IDC_ARROW);  wcl.lpszMenuName = NULL;  //  wcl.cbClsExtra = 0;  wcl.cbWndExtra = 0;  //  wcl.hbrBackground = (HBRUSH)::GetStockObject(BLACK_BRUSH);  //  if ( !::RegisterClass( &wcl ) )    {    //MessageBox(NULL,"qqqqqq",NULL,0);    return 0;    }  hWnd = ::CreateWindowEx( WS_EX_CLIENTEDGE, NAME_CLASS_SERVER, NAME_WINDOW_SERVER,              WS_OVERLAPPEDWINDOW, 384, 256, 256, 256, HWND_DESKTOP,NULL,hInstance,NULL);  if ( !::IsWindow( hWnd ) )    return 0;  g_hWnd = hWnd;  MyStart();  while ( ::GetMessage( &msg, NULL, 0, 0 ) )    {    ::TranslateMessage( &msg );    ::DispatchMessage( &msg );    }  MyStop();  return (int)msg.wParam; }//HINSTANCE g_hInstStart = NULL;//LRESULT CALLBACK WindowFunc( HWND hWnd, UINT uMsg, WPARAM wParam, LPARAM lParam )  {  static NOTIFYICONDATA NI;  if ( uMsg == nIconMessage && lParam == WM_RBUTTONUP )    {    HMENU hMenu = ::CreatePopupMenu();    if ( hMenu )      {      UINT u = MF_BYCOMMAND | MF_ENABLED;      if ( bDebugWnd )        {        if ( ::IsWindowVisible(hWnd) )          ::AppendMenu(hMenu,u,101,"Спрятать окно");        else          ::AppendMenu(hMenu,u,100,"Показать окно");        ::AppendMenu(hMenu,MF_SEPARATOR,0,0);        ::AppendMenu(hMenu,u,102,"Завершить работу...");        ::AppendMenu(hMenu,u,103,"Выход из меню");        }      else        {        ::AppendMenu(hMenu,u,102,"Завершить работу...");        ::AppendMenu(hMenu,MF_SEPARATOR,0,0);        ::AppendMenu(hMenu,u,103,"Выход из меню");        }      POINT point;      ::GetCursorPos( &point );      ::SetForegroundWindow(hWnd); //?      ::TrackPopupMenu(hMenu,TPM_LEFTALIGN|TPM_LEFTBUTTON|TPM_RIGHTBUTTON,                   point.x,point.y,0,hWnd,NULL);      ::DestroyMenu(hMenu);      }    }  // VM: 26.05.2021  // Используем WM_COPYDATA для генерирования события ЦПУ  if ( uMsg == WM_COPYDATA )  {		HWND hWndFrom = (HWND)wParam;		COPYDATASTRUCT *pData = (COPYDATASTRUCT*)lParam;		if ( pData != NULL )		{			CLogFile::Log ("WM_COPYDATA_1: pData->dwData %08lx, pData->cbData %d", (DWORD)pData->dwData, pData->cbData);			if ( pData->dwData == GENERATE_EVENT_ID && pData->cbData == sizeof(EXTEVENTDATA) )			{				CLogFile::Log ("WM_COPYDATA_2");				KServerThreadBase thread;				return thread.GenerateEvent(hWndFrom, pData->lpData);				//return TRUE;			}			else if ( pData->dwData == SET_EXRCSTATE_ID )			{				g_cExrcState.SetState ((BYTE *)pData->lpData, pData->cbData);				return TRUE;			}			else if ( pData->dwData == SET_ACTION_TIP_ID && pData->cbData == sizeof(ACTIONTIPDATA) )			{				g_cExrcState.SetUserTip ((PACTIONTIPDATA)pData->lpData);				return TRUE;			}		}		return FALSE;  }  else if ( uMsg == WM_REMOVE_TIP )  {	  int nUniqueIdx = (int)wParam;	  g_cExrcState.RemoveTip (nUniqueIdx);  }  // ...  if ( bDebugWnd && uMsg == nIconMessage && lParam == WM_LBUTTONDBLCLK )    {    ::ShowWindow( hWnd, SW_SHOWNORMAL );    ::SetForegroundWindow( hWnd );    }  switch ( uMsg )    {    case WM_CREATE:      {      NI.cbSize = sizeof ( NI );      NI.hWnd = hWnd;      NI.uID = 1001;      NI.uFlags = NIF_ICON|NIF_MESSAGE|NIF_TIP;      NI.uCallbackMessage = nIconMessage;      NI.hIcon = hIcon;      lstrcpy ( NI.szTip, NAME_WINDOW_SERVER );	    Shell_NotifyIcon( NIM_ADD, &NI );      }    break;    case WM_DESTROY:      {      static char szMessage[] =        "Завершение работы программы приведет\n"        "к отключению АРМ Оператора от сервера.\n\n"        "Продолжить закрытие программы?";      if( lParam != IDYES )      {        int nReturn = ::MessageBox( hWnd, szMessage, NAME_WINDOW_SERVER,                                    MB_YESNO | MB_ICONQUESTION | MB_DEFBUTTON2 );                  if ( nReturn != IDYES )                    return 0;      }  	  Shell_NotifyIcon( NIM_DELETE, &NI );       ::PostQuitMessage( 0 );      }    break;    case WM_SIZE:      {      if ( wParam == SIZE_MINIMIZED )        ::ShowWindow( hWnd, SW_HIDE );      }    break;    case WM_COMMAND:      {      switch ( LOWORD( wParam ) )        {        case 100:// Показать окно          ::ShowWindow( hWnd, SW_SHOWNORMAL );          ::SetForegroundWindow( hWnd );          break;        case 101:// Спрятать окно          ::ShowWindow( hWnd, SW_HIDE );          break;        case 102:// Завершить работу          ::PostMessage( hWnd, WM_DESTROY, 0, IDYES );          break;        case 103:// Выход          break;        }      }    break;    case WM_ERASEBKGND:      {      ::DefWindowProc( hWnd, uMsg, wParam, lParam );      HDC hDC = (HDC)wParam;      COLORREF color = ::SetTextColor( hDC, 0xFFFFFF );      int nMode = ::SetBkMode( hDC, TRANSPARENT );      char txt[64];      sprintf_s( txt, sizeof(txt), "Тренды: %d", b_hWnd );      ::TextOut( hDC, 10, 10, txt, lstrlen(txt) );      ::SetBkMode( hDC, nMode );      ::SetTextColor( hDC, color );      //::DrawIcon( hDC, 20, 20, hIcon );      ::DrawIconEx( hDC, 40, 40, hIcon, 100, 100, 0, 0, DI_IMAGE );      return 0;      }    break;    case WM_QUERYENDSESSION:      if ( g_hInstStart != NULL )        {        typedef void (WINAPI* LPFunc)();        LPFunc func = (LPFunc)GetProcAddress(g_hInstStart,"ModelStop");        if ( func != NULL )          (*func)();        ::FreeLibrary( g_hInstStart );        g_hInstStart = NULL;        }      break;    };  return ::DefWindowProc( hWnd, uMsg, wParam, lParam );  }/////////////////////////////////////////////////////////// Резиновый буфер//